mcp:tool-listener.mcp:parameters-schema:
{
      "type": "object",
      "properties": {
        "origin": { "type": "string", "description": "Origin airport code, e.g. COK" },
        "destination": { "type": "string", "description": "Destination airport code, e.g. DEL" },
        "date": { "type": "string", "description": "Travel date, format YYYY-MM-DD" }
      },
      "required": ["origin", "destination", "date"]
    }

{
      "type": "object",
      "properties": {
        "flightId": { "type": "string", "description": "The flight ID to book, e.g. SB101" },
        "passengerName": { "type": "string", "description": "Full name of the passenger" }
      },
      "required": ["flightId", "passengerName"]
    }

{
      "type": "object",
      "properties": {
        "city": { "type": "string", "description": "City code: DEL or BOM" },
        "checkIn": { "type": "string", "description": "Check-in date, YYYY-MM-DD" },
        "nights": { "type": "string", "description": "Number of nights, e.g. 5" }
      },
      "required": ["city", "checkIn", "nights"]
    }

{
      "type": "object",
      "properties": {
        "hotelId": { "type": "string", "description": "Hotel ID, e.g. H102" },
        "guestName": { "type": "string", "description": "Full name of the guest" },
        "checkIn": { "type": "string", "description": "Check-in date, YYYY-MM-DD" },
        "nights": { "type": "string", "description": "Number of nights, e.g. 5" }
      },
      "required": ["hotelId", "guestName", "checkIn", "nights"]
    }
